/*
 * Web Push for the installed app and browsers. The service worker generated by vite-plugin-pwa pulls
 * this in with importScripts. The server sends { id, title, body, url }; nothing here talks to any
 * outside service.
 */
self.addEventListener('push', (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    data = { title: 'Gauntlet', body: event.data ? event.data.text() : '' };
  }
  event.waitUntil(
    self.registration.showNotification(data.title || 'Gauntlet', {
      body: data.body || '',
      icon: '/icons/icon-192.png',
      badge: '/icons/icon-192.png',
      // The same notification twice replaces itself instead of stacking.
      tag: data.id || undefined,
      data: { url: data.url || '/notifications', id: data.id || null },
    }),
  );
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const wanted = (event.notification.data && event.notification.data.url) || '/';
  const url = new URL(wanted, self.location.origin).href;
  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
      for (const client of windows) {
        if (new URL(client.url).origin !== self.location.origin) continue;
        try {
          await client.focus();
          if ('navigate' in client) await client.navigate(url);
          return;
        } catch {
          // Fall through to opening a new window.
        }
      }
      await self.clients.openWindow(url);
    })(),
  );
});
